function readSession(){try{return JSON.parse(localStorage.getItem("bloom_session")||"null")}catch{return null}}
function saveSession(d){session={accessToken:d.accessToken,refreshToken:d.refreshToken,user:d.user};localStorage.setItem("bloom_session",JSON.stringify(session))}
function money(v){return new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(Number(v||0))}
function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function dateText(v){return v?new Date(v+"T12:00:00").toLocaleDateString():""}
function toast(m){const e=$("#toast");e.textContent=m;e.hidden=false;clearTimeout(window.bt);window.bt=setTimeout(()=>e.hidden=true,3200)}
function empty(t){return `<div class="card subtle">${esc(t)}</div>`}
async function api(path,opt={},auth=true){const h={"Content-Type":"application/json",...(opt.headers||{})};if(auth&&session?.accessToken)h.Authorization=`Bearer ${session.accessToken}`;const r=await fetch(`/.netlify/functions/${path}`,{...opt,headers:h});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||`Request failed (${r.status})`);return d}
function showAuth(){$("#auth").hidden=false;$("#app").hidden=true}
function showApp(){$("#auth").hidden=true;$("#app").hidden=false;$("#accountEmail").textContent=session?.user?.email||"";loadStores()}
function showPage(id){$$(".page").forEach(p=>p.classList.toggle("active",p.id===id));$$("[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===id));loadPage(id)}
async function loadPage(id){const m={customersPage:loadCustomers,ordersPage:loadOrders,deliveriesPage:loadDeliveries,inventoryPage:loadInventory,productsPage:loadProducts,websitePage:loadWebsite,libraryPage:renderLibrary,expensesPage:loadExpenses,reportsPage:loadReports,staffPage:loadStaff,marketplacePage:loadMarketplace,storesPage:loadStores,settingsPage:loadSettings,invoicesPage:loadInvoices};try{if(m[id])await m[id]()}catch(e){toast(e.message)}}
function renderOrder(o){return `<article class="card"><div class="card-top"><div><h3>${esc(o.order_number)} · ${esc(o.customer_name)}</h3><div class="meta">${esc(o.occasion||"Floral order")} · ${esc(o.fulfillment)} ${dateText(o.delivery_date)}</div></div><span class="badge ${o.payment_status==="PAID"?"good":"warn"}">${esc(o.payment_status||"UNPAID")}</span></div><p><strong>${money(o.total)}</strong>${o.recipient_name?` · For ${esc(o.recipient_name)}`:""}</p><div class="card-actions"><button class="secondary" data-receipt="${o.id}">Receipt</button>${o.payment_status==="PAID"?`<button class="secondary" data-unpay="${o.id}">Mark unpaid</button>`:`<button class="primary" data-pay="${o.id}">Mark paid</button>`}</div></article>`}

function invoiceCard(o){const paid=(o.payment_status||"UNPAID")==="PAID";return `<article class="card invoice-card"><div class="card-top"><div><h3>Invoice ${esc(o.order_number||"")}</h3><div class="meta">${esc(o.customer_name||"Customer")} · ${dateText((o.created_at||"").slice(0,10))}</div></div><span class="badge ${paid?"good":"warn"}">${paid?"PAID":"OPEN"}</span></div><p>${esc(o.recipient_name?`Recipient: ${o.recipient_name}`:(o.occasion||"Floral order"))}</p><div class="invoice-amount"><span>Total</span><strong>${money(o.total)}</strong></div><div class="card-actions"><button class="secondary" data-invoice-view="${o.id}" type="button">View / print</button><button class="secondary" data-invoice-email="${o.id}" type="button">Email invoice</button>${paid?`<button class="secondary" data-unpay="${o.id}" type="button">Mark unpaid</button>`:`<button class="primary" data-pay="${o.id}" type="button">Mark paid</button>`}</div></article>`}
async function loadInvoices(){if(!orders.length)await loadOrders();const outstanding=orders.filter(o=>(o.payment_status||"UNPAID")!=="PAID");$("#invoiceOutstanding").textContent=money(outstanding.reduce((s,o)=>s+Number(o.total||0),0));$("#invoiceOpenCount").textContent=outstanding.length;$("#invoicePaidCount").textContent=orders.length-outstanding.length;$("#invoiceList").innerHTML=orders.length?orders.map(invoiceCard).join(""):empty("No invoices yet. Create an order first.")}
function openInvoice(o){if(!o)return;openReceipt(o)}
function emailInvoice(o){if(!o)return;const subject=encodeURIComponent(`Invoice ${o.order_number||""} from ${shopSettings?.name||"Bloom"}`);const body=encodeURIComponent(`Hello ${o.customer_name||""},\n\nYour floral invoice total is ${money(o.total)}. Payment status: ${o.payment_status||"UNPAID"}.\n\nThank you,\n${shopSettings?.name||"Bloom"}`);location.href=`mailto:?subject=${subject}&body=${body}`}

async function loadDashboard(){
  const d=await api("dashboard");
  const date=new Date();
  $("#dashboardDate").textContent=date.toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"});
  $("#todaySales").textContent=money(d.todaySales);
  $("#totalSales").textContent=money(d.totalSales);
  $("#totalExpenses").textContent=money(d.totalExpenses);
  $("#profit").textContent=money(d.profit);
  $("#unpaidTotal").textContent=money(d.unpaidTotal);
  $("#ordersDueToday").textContent=d.ordersDueToday||0;
  $("#deliveriesToday").textContent=d.deliveriesToday||0;
  $("#lowStock").textContent=d.lowStock||0;
  $("#customerCount").textContent=d.customers||0;
  $("#weekSales").textContent=money(d.weekSales);
  $("#ordersTodayLabel").textContent=`${d.ordersToday||0} order${d.ordersToday===1?"":"s"} created today`;
  $("#deliveriesStatus").textContent=`${d.deliveries||0} still active`;
  $("#queue").innerHTML=d.queue?.length?d.queue.slice(0,5).map(renderOrder).join(""):empty("No active orders. Enjoy the breathing room!");
  const chart=d.weeklySales||[];
  const max=Math.max(...chart.map(x=>Number(x.total||0)),1);
  $("#salesChart").innerHTML=chart.map(x=>`<div class="chart-day"><div class="chart-value">${money(x.total)}</div><div class="chart-bar-wrap"><div class="chart-bar" style="height:${Math.max(5,Math.round(Number(x.total||0)/max*100))}%"></div></div><small>${esc(x.label)}</small></div>`).join("");
  $("#upcomingDeliveries").innerHTML=d.upcomingDeliveries?.length?d.upcomingDeliveries.map(o=>`<article><div><strong>${esc(o.recipient_name||o.customer_name||"Delivery")}</strong><small>${esc(o.order_number||"")} · ${dateText(o.delivery_date)}</small></div><span class="badge ${o.status==="COMPLETED"?"good":"warn"}">${esc(o.status||"PENDING")}</span></article>`).join(""):empty("No upcoming deliveries.");
}
async function loadStores(){const {items}=await api("stores");$("#shopSwitcher").innerHTML=items.map(s=>`<option value="${s.id}" ${s.active?"selected":""}>${esc(s.name)}</option>`).join("");const active=items.find(x=>x.active);$("#greeting").textContent=`Welcome to ${active?.name||"Bloom"}`;if($("#storesList"))$("#storesList").innerHTML=items.length?items.map(s=>`<article class="card"><div class="card-top"><div><h3>${esc(s.name)}</h3><div class="meta">${esc(s.address||"Address not set")} · ${esc(s.role)}</div></div>${s.active?'<span class="badge good">ACTIVE</span>':""}</div>${!s.active?`<div class="card-actions"><button class="primary" data-switch-shop="${s.id}">Open this shop</button></div>`:""}</article>`).join(""):empty("No stores.")}
async function loadCustomers(){customers=(await api("customers")).items||[];renderCustomers();refreshOrderCustomerOptions()}
function renderCustomers(){const q=$("#customerSearch").value.toLowerCase();const rows=customers.filter(x=>[x.name,x.phone,x.email,x.favorite_flowers,x.favorite_colors].join(" ").toLowerCase().includes(q));$("#customersList").innerHTML=rows.length?rows.map(c=>`<article class="card"><div class="card-top"><div><h3>${c.vip?"★ ":""}${esc(c.name)}</h3><div class="meta">${esc(c.phone||"")} ${c.email?`· ${esc(c.email)}`:""}</div></div>${c.vip?'<span class="badge">VIP</span>':""}${c.is_business?'<span class="badge good">BUSINESS</span>':""}</div>${c.favorite_flowers?`<p>Favorites: ${esc(c.favorite_flowers)} ${c.favorite_colors?`· ${esc(c.favorite_colors)}`:""}</p>`:""}<div class="card-actions"><button class="secondary" data-edit-customer="${c.id}">Edit</button><button class="secondary" data-delete-customer="${c.id}">Delete</button></div></article>`).join(""):empty("No customers found.")}
async function loadOrders(){orders=(await api("orders")).items||[];$("#ordersList").innerHTML=orders.length?orders.map(renderOrder).join(""):empty("No orders.");$("#deliveryOrder").innerHTML=orders.map(o=>`<option value="${o.id}" data-address="${esc(o.delivery_address||"")}">${esc(o.order_number)} · ${esc(o.customer_name)}</option>`).join("");syncDeliveryStopAddress()}
async function loadInventory(){
  inventory=(await api("inventory")).items||[];
  const colors=[...new Set(inventory.map(i=>(i.color||"").trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  const select=$("#inventoryColorFilter");
  if(select){const current=select.value;select.innerHTML='<option value="">All colors</option>'+colors.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join("");select.value=colors.includes(current)?current:""}
  if($("#inventoryColorTabs"))$("#inventoryColorTabs").innerHTML=['All',...colors].map(c=>`<button class="${(select?.value||"")===(c==='All'?'':c)?'active':''}" data-inventory-color="${esc(c==='All'?'':c)}">${esc(c)}</button>`).join("");
  renderInventory();
}
function renderInventory(){
  const q=($("#inventorySearch")?.value||"").trim().toLowerCase(),color=$("#inventoryColorFilter")?.value||"";
  const rows=inventory.filter(i=>!color||(i.color||"")===color).filter(i=>[i.name,i.category,i.color,i.variety].join(" ").toLowerCase().includes(q));
  const retail=rows.reduce((sum,i)=>sum+Number(i.quantity||0)*Number(i.price||0),0);if($("#inventoryRetailValue"))$("#inventoryRetailValue").textContent=money(retail);
  $("#inventoryList").innerHTML=rows.length?rows.map(i=>`<article class="card inventory-card"><div class="card-top"><div><div class="inventory-title-row"><h3>${esc(i.name)}</h3>${i.color?`<span class="color-label">${esc(i.color)}</span>`:""}</div><div class="meta">${esc(i.category)}${i.variety?` · ${esc(i.variety)}`:""} · ${Number(i.quantity||0)} ${esc(i.unit)}</div></div><span class="badge ${Number(i.quantity)<=Number(i.low_stock_level)?"warn":"good"}">${Number(i.quantity)<=Number(i.low_stock_level)?"LOW":"IN STOCK"}</span></div><div class="inventory-pricing"><span>Wholesale <strong>${money(i.cost)}</strong></span><span>Retail <strong>${money(i.price)}</strong></span><span>Stock retail value <strong>${money(Number(i.quantity||0)*Number(i.price||0))}</strong></span></div><div class="card-actions"><button class="secondary" data-edit-inventory="${i.id}">Edit</button><button class="secondary" data-delete-inventory="${i.id}">Delete</button></div></article>`).join(""):empty("No inventory matches this view.")
}
async function loadProducts(){products=(await api("products")).items||[];$("#productsList").innerHTML=products.length?products.map(productCard).join(""):empty("Create your first product.");$("#orderProduct").innerHTML='<option value="">Custom arrangement</option>'+products.map(p=>`<option value="${p.id}" data-price="${p.price}" data-cost="${p.estimated_cost||p.labor_cost||0}">${esc(p.name)} · ${money(p.price)}</option>`).join("")}
function productCard(p){return `<article class="product-card">${p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}">`:`<div class="product-art">💐</div>`}<div class="body"><span class="badge">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p class="meta">${esc(p.description||"")}</p><div class="price">${money(p.price)}</div><div class="product-status"><span class="badge ${p.available_online?'good':'warn'}">${p.available_online?'ONLINE':'NOT ONLINE'}</span></div><div class="card-actions"><button class="secondary" data-edit-product="${p.id}">Edit + recipe</button><button class="secondary" data-duplicate-product="${p.id}">Duplicate</button><button class="secondary" data-publish-product="${p.id}">${p.available_online?'Remove from website':'Publish to website'}</button><button class="secondary danger" data-delete-product="${p.id}">Delete</button></div></div></article>`}
function renderLibrary(){const q=( $("#librarySearch")?.value||"").toLowerCase(),cat=$("#libraryCategory")?.value||"";const rows=LIBRARY.map((p,i)=>({p,i})).filter(({p})=>(!q||`${p[0]} ${p[1]} ${p[4]} ${p[5].map(r=>r[0]).join(" ")}`.toLowerCase().includes(q))&&(!cat||p[1]===cat));$("#libraryList").innerHTML=rows.length?rows.map(({p,i})=>`<article class="product-card floral-library-card" data-library-card="${i}">${p[6]?`<img src="${esc(p[6])}" alt="${esc(p[0])} floral arrangement" loading="lazy">`:`<div class="product-art">${p[3]}</div>`}<div class="body"><span class="badge">${esc(p[1])}</span><h3>${esc(p[0])}</h3><p>${esc(p[4])}</p><div class="price">${money(p[2])}</div><div class="recipe-preview"><strong>Starter recipe</strong><span>${p[5].map(r=>`${r[1]} ${esc(r[0])}`).join(" · ")}</span></div><div class="card-actions"><button type="button" class="secondary" data-preview-library="${i}">View & edit</button><button type="button" class="primary" data-add-library="${i}">Add to my products</button></div></div></article>`).join(""):empty("No floral designs match that search.")}
async function loadMarketplace(){const a=(await api("marketplace")).items||[];$("#marketplaceList").innerHTML=a.length?a.map(x=>`<article class="product-card">${x.image_url?`<img src="${esc(x.image_url)}">`:`<div class="product-art">🌹</div>`}<div class="body"><span class="badge">${esc(x.category)}</span><h3>${esc(x.product_name)}</h3><p>${esc(x.supplier_name)}</p><div class="price">${money(x.price)} / ${esc(x.unit)}</div><p class="meta">Minimum ${x.minimum_quantity}</p><button class="secondary wide" data-market-request="${x.id}">Create purchase request</button></div></article>`).join(""):empty("No wholesale listings.")}
async function loadExpenses(){expenses=(await api("expenses")).items||[];$("#expensesList").innerHTML=expenses.length?expenses.map(x=>`<article class="card"><div class="card-top"><div><h3>${esc(x.vendor||x.category)}</h3><div class="meta">${dateText(x.expense_date)} · ${esc(x.category)}</div></div><strong>${money(x.amount)}</strong></div>${x.notes?`<p>${esc(x.notes)}</p>`:""}${x.receipt_url?`<p><a class="secondary receipt-link" href="${esc(x.receipt_url)}" target="_blank" rel="noopener">Open receipt</a></p>`:`<p class="subtle">No receipt attached</p>`}<div class="card-actions"><button type="button" class="secondary" data-edit-expense="${x.id}">Edit expense</button><button type="button" class="secondary danger" data-delete-expense="${x.id}">Delete expense</button></div></article>`).join(""):empty("No expenses.")}
async function loadReports(){const d=await api("finance"),a=d.months||d.items||[];$("#financeList").innerHTML=a.length?a.map(x=>`<div class="report-row"><strong>${esc(x.month||x.label||"Period")}</strong><span>Revenue ${money(x.revenue)}</span><span>Expenses ${money(x.expenses)}</span><span>Profit ${money(x.profit)}</span></div>`).join(""):empty("No report data.")}
async function loadWebsite(){shopSettings=(await api("settings")).item;const f=$("#websiteForm");for(const[k,v]of Object.entries(shopSettings||{})){if(!f.elements[k])continue;if(f.elements[k].type==="checkbox")f.elements[k].checked=Boolean(v);else f.elements[k].value=v??""}renderWebsite()}

async function loadSettings(){shopSettings=(await api("settings")).item;const f=$("#settingsForm");for(const[k,v]of Object.entries(shopSettings||{})){if(f.elements[k])f.elements[k].value=v??""}$("#mapsStatus").textContent="Shop defaults loaded. Use Calculate mileage on a delivery order to test the route service."}
async function calculateRoute(showMessage=true){const f=$("#orderForm"),address=f.elements.delivery_address.value.trim();if(!address){if(showMessage)toast("Enter the delivery address first");return null}const result=$("#routeResult");result.textContent="Calculating driving route…";try{const d=await api("route-distance",{method:"POST",body:JSON.stringify({destination:address})});f.elements.delivery_miles.value=Number(d.roundTripMiles||0).toFixed(1);f.elements.drive_minutes.value=Math.round(Number(d.driveMinutes||0));result.textContent=`${Number(d.oneWayMiles).toFixed(1)} miles one way · ${Number(d.roundTripMiles).toFixed(1)} round trip · about ${Math.round(Number(d.driveMinutes))} minutes`;return d}catch(e){result.textContent=e.message;if(showMessage)toast(e.message);return null}}
function renderWebsite(){const f=$("#websiteForm"),d=Object.fromEntries(new FormData(f)),main=d.primary_color||"#a72f67",accent=d.accent_color||"#6f8f72",hero=d.hero_image_url?`url('${d.hero_image_url}')`:`linear-gradient(135deg,${main},${accent})`;const pv=$("#websitePreview");pv.style.setProperty("--site-main",main);pv.style.setProperty("--site-accent",accent);pv.style.setProperty("--hero-image",hero);const online=products.filter(p=>p.available_online).slice(0,6);const cards=(online.length?online:[{name:"Hydrangea Garden",price:85,image_url:"https://images.pexels.com/photos/931177/pexels-photo-931177.jpeg?auto=compress&cs=tinysrgb&w=700"},{name:"Seasonal Designer's Choice",price:75,image_url:"https://images.pexels.com/photos/1458694/pexels-photo-1458694.jpeg?auto=compress&cs=tinysrgb&w=700"},{name:"Romantic Roses",price:95,image_url:"https://images.pexels.com/photos/1070850/pexels-photo-1070850.jpeg?auto=compress&cs=tinysrgb&w=700"}]);pv.innerHTML=`<div class="preview-announcement">Fresh flowers · Thoughtful design · Local delivery</div><div class="preview-nav">${d.logo_url?`<img src="${esc(d.logo_url)}">`:""}<strong>${esc(d.name||"Your Flower Shop")}</strong><span>Shop Flowers · Occasions · Weddings · Sympathy · About</span><button>Order flowers</button></div><div class="preview-hero"><div class="hero-copy"><p>${esc(d.tagline||d.website_style||"Local florist")}</p><h2>${esc(d.hero_title||"Flowers made beautifully for every moment")}</h2><div>${esc(d.hero_text||"Thoughtful floral designs, gifts, and local delivery.")}</div><button>Shop the collection</button></div></div><section class="preview-occasions"><span>Birthday</span><span>Love & Romance</span><span>Sympathy</span><span>Wedding</span></section><section class="preview-featured"><p class="eyebrow">SHOP OUR FAVORITES</p><h3>Featured arrangements</h3><div class="preview-product-grid">${cards.map(p=>`<article>${p.image_url?`<img src="${esc(p.image_url)}" alt="${esc(p.name)}">`:`<div class="preview-product-placeholder">Fresh Flowers</div>`}<strong>${esc(p.name)}</strong><small>${money(p.price||0)}</small><button>View arrangement</button></article>`).join("")}</div></section><section class="preview-story"><div><p class="eyebrow">DESIGNED LOCALLY</p><h3>Flowers with heart</h3><p>${esc(d.about_text||"Every arrangement is designed by hand with fresh flowers and personal attention.")}</p></div><div class="preview-story-card"><b>Local delivery</b><span>${esc(d.address||"Your delivery area")}</span><b>Talk to a florist</b><span>${esc(d.phone||"Your phone number")}</span></div></section><footer><strong>${esc(d.name||"Your Flower Shop")}</strong><span>${esc(d.phone||"Phone")} · ${esc(d.address||"Local delivery")}</span>${d.custom_domain?`<span>${esc(d.custom_domain)}</span>`:""}</footer>`}
function openCustomer(x=null){const f=$("#customerForm");f.reset();for(const k of["id","name","phone","email","address","birthday","anniversary","favorite_flowers","favorite_colors","notes"])f.elements[k].value=x?.[k]||"";f.elements.vip.checked=Boolean(x?.vip);$("#customerDialogTitle").textContent=x?"Edit customer":"Add customer";$("#customerDialog").showModal()}
function updateInventoryPrice(force=false){const f=$("#inventoryForm"),category=f.elements.category.value,cost=Number(f.elements.cost.value||0),quantity=Number(f.elements.quantity.value||0);if(category==="Flowers"&&(force||!f.elements.price.dataset.manual))f.elements.price.value=(cost*3).toFixed(2);$("#inventoryMarkupNote").textContent=category==="Flowers"?"Flowers automatically price at 3× wholesale.":"Set the retail price for this item.";$("#wholesaleStockValue").textContent=money(cost*quantity);$("#retailStockValue").textContent=money(Number(f.elements.price.value||0)*quantity)}
function openInventory(x=null){const f=$("#inventoryForm");f.reset();f.elements.price.dataset.manual="";for(const k of["id","name","category","color","variety","quantity","low_stock_level","unit","cost","price"])if(f.elements[k])f.elements[k].value=x?.[k]??(k==="unit"?"stems":"");if(x)f.elements.price.dataset.manual="1";$("#inventoryDialogTitle").textContent=x?"Edit inventory":"Add inventory";updateInventoryPrice(!x);$("#inventoryDialog").showModal()}
