function refreshOrderCustomerOptions(){const list=$("#customerOptions");if(list)list.innerHTML=customers.map(c=>`<option value="${esc(c.name)}" data-id="${c.id}">${esc(c.phone||c.email||"")}</option>`).join("")}
function orderNumber(form,name){return Number(form.elements[name]?.value||0)}
function updateOrderBuilder(){const f=$("#orderForm");if(!f)return;const subtotal=orderNumber(f,"subtotal"),labor=orderNumber(f,"labor_charge"),addons=orderNumber(f,"addon_total"),delivery=orderNumber(f,"delivery_fee"),discount=orderNumber(f,"discount"),taxRate=orderNumber(f,"tax_rate"),cost=orderNumber(f,"estimated_cost");const taxable=Math.max(0,subtotal+labor+addons-discount);const tax=Math.round(taxable*(taxRate/100)*100)/100;if(f.elements.tax)f.elements.tax.value=tax.toFixed(2);const total=Math.max(0,taxable+delivery+tax),profit=total-cost;$("#orderTaxAmount").textContent=money(tax);$("#orderLiveTotal").textContent=money(total);$("#orderSummaryTotal").textContent=money(total);$("#orderSummaryProfit").textContent=money(profit);$("#orderProfitPreview").textContent=`Estimated profit ${money(profit)}`;const product=f.elements.product_id.selectedOptions[0];$("#orderSuggestion").textContent=product?.value?`${product.textContent} selected. Review recipe cost and add delivery or add-ons before saving.`:"Custom order: use the description, flower preferences, and estimated material cost so the designer has a complete worksheet."}
async function prepareOrderBuilder(){const f=$("#orderForm");f.reset();f.elements.delivery_date.value=new Date().toISOString().slice(0,10);if(!shopSettings)try{shopSettings=(await api("settings")).item}catch{};f.elements.tax_rate.value=Number(shopSettings?.tax_rate??6);f.elements.fulfillment.value="DELIVERY";f.elements.delivery_fee.value=Number(shopSettings?.default_delivery_fee??0).toFixed(2);if(!customers.length)try{await loadCustomers()}catch{}if(!products.length)try{await loadProducts()}catch{}refreshOrderCustomerOptions();toggleDeliveryFields();updateOrderBuilder()}
