$("#saveSettings").onclick=async()=>{const f=$("#settingsForm"),d=Object.fromEntries(new FormData(f));try{shopSettings=(await api("settings",{method:"PATCH",body:JSON.stringify(d)})).item;toast("Shop settings saved");$("#mapsStatus").textContent="Saved. This address will be used as the starting point for delivery routes."}catch(e){toast(e.message);$("#mapsStatus").textContent=e.message}};
