$$('[data-hero-image]').forEach(b=>b.onclick=()=>{$("#heroImageUrl").value=b.dataset.heroImage;renderWebsite();toast("Website photo selected")});
$("#heroImageUpload")?.addEventListener("change",e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>900*1024)return toast("Please use a photo under 900 KB");const reader=new FileReader();reader.onload=()=>{$("#heroImageUrl").value=reader.result;renderWebsite();toast("Your arrangement photo is now in the preview")};reader.readAsDataURL(file)});
$$('[data-gallery-filter]').forEach(b=>b.onclick=()=>{$$('[data-gallery-filter]').forEach(x=>x.classList.remove("active"));b.classList.add("active");const filter=b.dataset.galleryFilter;$$('.photo-gallery [data-category]').forEach(card=>card.hidden=filter!=="all"&&card.dataset.category!==filter)});
async function duplicateProduct(id){const source=products.find(x=>x.id===id);if(!source)return;const recipe=(await api(`recipes?product_id=${id}`)).items||[];const payload={...source,id:undefined,name:`${source.name} Copy`,sku:source.sku?`${source.sku}-COPY`:"",available_online:false,featured:false};const {item}=await api("products",{method:"POST",body:JSON.stringify(payload)});await api("recipes",{method:"POST",body:JSON.stringify({product_id:item.id,items:recipe.map(r=>({ingredient_name:r.ingredient_name,quantity:r.quantity,unit:r.unit,unit_cost:r.unit_cost}))})});await loadProducts();toast(`${item.name} duplicated`)}
async function toggleProductPublish(id){const product=products.find(x=>x.id===id);if(!product)return;await api("products",{method:"PATCH",body:JSON.stringify({id,available_online:!product.available_online,active:true})});await loadProducts();renderWebsite();toast(product.available_online?"Removed from website":"Published to website")}
function setAssistantPersona(name){assistantPersona=name;$$('[data-persona]').forEach(b=>b.classList.toggle('active',b.dataset.persona===name));const input=$("#assistantPrompt");if(input&&!input.value.trim())input.placeholder=name==="Lily"?"Lily, help me design and price a bouquet…":"Rose, tell me what needs my attention today…"}
function preferredVoice(persona){const voices=window.speechSynthesis?.getVoices?.()||[];const english=voices.filter(v=>/^en[-_]/i.test(v.lang||""));const pool=english.length?english:voices;if(persona==="Rose")return pool.find(v=>/samantha|victoria|karen|moira|zira|female/i.test(v.name))||pool[1]||pool[0];return pool.find(v=>/aria|jenny|ava|susan|female/i.test(v.name))||pool[0]}
function speakAssistant(text,persona,force=false){if((!force&&!$("#assistantSpeak")?.checked)||!window.speechSynthesis||!text)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.voice=preferredVoice(persona);u.rate=persona==="Rose"?.92:1.02;u.pitch=persona==="Rose"?.88:1.12;window.speechSynthesis.speak(u)}
async function runAssistant(rawPrompt,persona=assistantPersona){let prompt=(rawPrompt??$("#assistantPrompt")?.value??"").trim();if(!prompt)return toast("Ask Lily or Rose a question first");setAssistantPersona(persona);if(!new RegExp(`^${persona}\\b`,"i").test(prompt))prompt=`${persona}, ${prompt}`;const out=$("#assistantAnswer");out.textContent=`${persona} is thinking…`;try{const d=await api("ai-assistant",{method:"POST",body:JSON.stringify({prompt,persona})});out.textContent=d.answer;speakAssistant(d.answer,d.persona||persona)}catch(e){out.textContent=e.message}}
$$('[data-persona]').forEach(b=>b.onclick=()=>{setAssistantPersona(b.dataset.persona);$("#assistantPrompt").focus()});
$$('[data-assistant-prompt]').forEach(b=>b.onclick=()=>{const prompt=b.dataset.assistantPrompt;assistantPersona=/^Rose\b/i.test(prompt)?"Rose":"Lily";setAssistantPersona(assistantPersona);$("#assistantPrompt").value=prompt;$("#assistantPrompt").focus()});
setAssistantPersona("Lily");
$("#assistantMic")?.addEventListener("click",()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast("Voice questions are not supported in this browser. You can still type your question.");const r=new SR();r.lang="en-US";r.interimResults=false;r.maxAlternatives=1;const listening=$("#assistantListening");listening.hidden=false;r.onresult=e=>{$("#assistantPrompt").value=e.results[0][0].transcript;listening.hidden=true};r.onerror=()=>{listening.hidden=true;toast("I couldn't hear that clearly. Please try again.")};r.onend=()=>{listening.hidden=true};r.start()});
$("#assistantRun").onclick=()=>runAssistant();

async function runContentHelper(button){const target=document.getElementById(button.dataset.aiTarget);if(!target)return;const form=button.closest("form"),fields=form?Object.fromEntries(new FormData(form)):{};const original=button.textContent;button.disabled=true;button.textContent="Lily is writing…";try{const d=await api("content-helper",{method:"POST",body:JSON.stringify({kind:button.dataset.aiKind||"description",current:target.value||"",fields})});target.value=d.text||"";target.dispatchEvent(new Event("input",{bubbles:true}));toast("Lily added polished wording. Review it, then save.")}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent=original}}
document.addEventListener("click",e=>{const b=e.target.closest("[data-ai-target]");if(b)runContentHelper(b)});
$("#librarySearch")?.addEventListener("input",renderLibrary);$("#libraryCategory")?.addEventListener("change",renderLibrary);
$("#addLibraryRecipeLine")?.addEventListener("click",()=>{$("#libraryRecipeRows").insertAdjacentHTML("beforeend",libraryRecipeRows([["",1]]))});
$("#libraryDesignForm")?.addEventListener("submit",async e=>{e.preventDefault();const b=$("#addLibraryDesignButton");b.disabled=true;try{await addLibraryProduct()}finally{b.disabled=false}});

let wakeRecognition=null,wakeEnabled=false,wakeRestartTimer=null,wakeBusy=false,wakeAwaitingPersona=null,wakeIgnoreUntil=0;
function wakeUi(message,state="") {const box=$("#assistantWakeToggle")?.parentElement,status=$("#assistantWakeStatus"),button=$("#assistantWakeToggle");if(status)status.textContent=message;if(box){box.classList.toggle("active",wakeEnabled);box.classList.toggle("listening",state==="listening");box.classList.toggle("error",state==="error")}if(button)button.textContent=wakeEnabled?'⏹ Turn off “Hey Lily / Hey Rose”':'🎙️ Turn on “Hey Lily / Hey Rose”'}
function stopWakeListening(){wakeEnabled=false;clearTimeout(wakeRestartTimer);wakeRestartTimer=null;try{wakeRecognition?.stop()}catch{}wakeRecognition=null;wakeBusy=false;wakeAwaitingPersona=null;wakeUi("Hands-free listening is off.")}
function acknowledgeWake(persona){const response=persona==="Rose"?"Yes, honey? What do you need?":"Yes! What can I do for you?";const out=$("#assistantAnswer");if(out)out.textContent=`${persona}: ${response}`;speakAssistant(response,persona,true)}
function handleWakeTranscript(transcript){if(Date.now()<wakeIgnoreUntil||wakeBusy)return;const clean=(transcript||"").trim();const match=clean.match(/(?:hey\s+)?(lily|rose)\b[\s,.:;-]*(.*)$/i);if(!match){if(wakeAwaitingPersona&&clean){const persona=wakeAwaitingPersona;wakeAwaitingPersona=null;$("#assistantPrompt").value=clean;wakeBusy=true;runAssistant(clean,persona).finally(()=>{wakeBusy=false})}return}const persona=match[1].toLowerCase()==="rose"?"Rose":"Lily";const command=(match[2]||"").trim();assistantPersona=persona;setAssistantPersona(persona);wakeIgnoreUntil=Date.now()+1200;acknowledgeWake(persona);if(command){wakeAwaitingPersona=null;$("#assistantPrompt").value=command;wakeBusy=true;setTimeout(()=>runAssistant(command,persona).finally(()=>{wakeBusy=false}),650)}else{wakeAwaitingPersona=persona;$("#assistantPrompt").value="";wakeUi(`${persona} heard you. Say your question now…`,"listening")}}
function startWakeListening(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){wakeUi("Hands-free wake phrases are not supported in this browser. Use Chrome or Edge.","error");return}wakeEnabled=true;wakeRecognition=new SR();wakeRecognition.lang="en-US";wakeRecognition.continuous=true;wakeRecognition.interimResults=false;wakeRecognition.maxAlternatives=1;wakeRecognition.onstart=()=>wakeUi('Listening for “Hey Lily” or “Hey Rose”…',"listening");wakeRecognition.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)handleWakeTranscript(e.results[i][0].transcript)}};wakeRecognition.onerror=e=>{if(e.error==="not-allowed"||e.error==="service-not-allowed"){wakeEnabled=false;wakeUi("Microphone permission was blocked. Allow microphone access, then turn this on again.","error")}else if(e.error!=="no-speech"&&e.error!=="aborted")wakeUi(`Voice listening paused: ${e.error}. Retrying…`,"error")};wakeRecognition.onend=()=>{wakeRecognition=null;if(wakeEnabled){clearTimeout(wakeRestartTimer);wakeRestartTimer=setTimeout(()=>{if(wakeEnabled&&!wakeBusy)startWakeListening()},500)}};try{wakeRecognition.start()}catch(e){wakeUi("Could not start microphone listening. Refresh and try again.","error")}}
$("#assistantWakeToggle")?.addEventListener("click",()=>wakeEnabled?stopWakeListening():startWakeListening());
document.addEventListener("visibilitychange",()=>{if(document.hidden&&wakeRecognition){try{wakeRecognition.stop()}catch{}}else if(!document.hidden&&wakeEnabled&&!wakeRecognition)startWakeListening()});
document.addEventListener("click",async e=>{let t;
if(t=e.target.closest("[data-edit-customer]"))return openCustomer(customers.find(x=>x.id===t.dataset.editCustomer));
if(t=e.target.closest("[data-delete-customer]")){if(confirm("Delete this customer?")){await api("customers",{method:"DELETE",body:JSON.stringify({id:t.dataset.deleteCustomer})});loadCustomers()}return}
if(t=e.target.closest("[data-inventory-color]")){$("#inventoryColorFilter").value=t.dataset.inventoryColor;renderInventory();$$(`[data-inventory-color]`).forEach(x=>x.classList.toggle("active",x===t));return}
if(t=e.target.closest("[data-edit-inventory]"))return openInventory(inventory.find(x=>x.id===t.dataset.editInventory));
if(t=e.target.closest("[data-delete-inventory]")){if(confirm("Delete this item?")){await api("inventory",{method:"DELETE",body:JSON.stringify({id:t.dataset.deleteInventory})});loadInventory()}return}
if(t=e.target.closest("[data-edit-expense]"))return openExpense(expenses.find(x=>x.id===t.dataset.editExpense));
if(t=e.target.closest("[data-delete-expense]")){if(confirm("Delete this expense? This cannot be undone.")){await api("expenses",{method:"DELETE",body:JSON.stringify({id:t.dataset.deleteExpense})});loadExpenses();loadDashboard()}return}
if(t=e.target.closest("[data-preview-library]"))return openLibraryDesign(t.dataset.previewLibrary);
if(t=e.target.closest("[data-library-card]")){if(!e.target.closest("button"))return openLibraryDesign(t.dataset.libraryCard)}
if(t=e.target.closest("[data-remove-library-line]")){t.closest(".library-recipe-row")?.remove();return}
if(t=e.target.closest("[data-duplicate-product]")){t.disabled=true;try{await duplicateProduct(t.dataset.duplicateProduct)}finally{t.disabled=false}return}
if(t=e.target.closest("[data-publish-product]")){t.disabled=true;try{await toggleProductPublish(t.dataset.publishProduct)}finally{t.disabled=false}return}
if(t=e.target.closest("[data-edit-product]"))return openProduct(products.find(x=>x.id===t.dataset.editProduct));
if(t=e.target.closest("[data-delete-product]")){if(confirm("Delete this product?")){await api("products",{method:"DELETE",body:JSON.stringify({id:t.dataset.deleteProduct})});loadProducts()}return}
if(t=e.target.closest("[data-add-library]")){t.disabled=true;try{await addLibraryProduct(t.dataset.addLibrary)}finally{t.disabled=false}return}
if(t=e.target.closest("[data-invoice-view]")){if(!shopSettings)shopSettings=(await api("settings")).item;return openInvoice(orders.find(x=>x.id===t.dataset.invoiceView))}
if(t=e.target.closest("[data-invoice-email]")){return emailInvoice(orders.find(x=>x.id===t.dataset.invoiceEmail))}
if(t=e.target.closest("[data-receipt]")){if(!shopSettings)shopSettings=(await api("settings")).item;return openReceipt(orders.find(x=>x.id===t.dataset.receipt))}
if(t=e.target.closest("[data-pay]")){const m=prompt("Payment method","Card");if(m){await api("orders",{method:"PATCH",body:JSON.stringify({id:t.dataset.pay,action:"MARK_PAID",payment_method:m})});loadOrders();loadDashboard()}return}
if(t=e.target.closest("[data-unpay]")){await api("orders",{method:"PATCH",body:JSON.stringify({id:t.dataset.unpay,action:"MARK_UNPAID"})});loadOrders();loadDashboard();return}
if(t=e.target.closest("[data-switch-shop]")){await api("stores",{method:"PATCH",body:JSON.stringify({shop_id:t.dataset.switchShop})});location.reload()}
if(t=e.target.closest("[data-advance-delivery]")){const a=["PENDING","ROUTED","OUT_FOR_DELIVERY","DELIVERED"],n=a[Math.min(a.indexOf(t.dataset.status)+1,3)];await api("deliveries",{method:"PATCH",body:JSON.stringify({id:t.dataset.advanceDelivery,status:n,delivered_at:n==="DELIVERED"?new Date().toISOString():null})});loadDeliveries()}
if(t=e.target.closest("[data-market-request]"))toast("Purchase request created. Live supplier checkout comes with Stripe Connect.");
});
$("#printManifest").onclick=()=>{document.body.classList.add("manifest-print");window.print();setTimeout(()=>document.body.classList.remove("manifest-print"),500)};
$("#closeReceipt").onclick=()=>$("#receiptDialog").close();$("#printReceipt").onclick=()=>window.print();$("#checkout").onclick=async()=>{const button=$("#checkout"),status=$("#paymentStatus"),amount=Number($("#paymentAmount").value||0),description=$("#paymentDescription").value.trim();if(amount<0.50){status.textContent="Enter a payment amount of at least $0.50.";$("#paymentAmount").focus();return}button.disabled=true;button.textContent="Opening Stripe…";status.textContent="Creating a secure checkout session…";try{const d=await api("create-checkout",{method:"POST",body:JSON.stringify({amount,description})});if(!d.url)throw new Error("Stripe did not return a checkout link.");status.textContent="Redirecting to Stripe…";location.assign(d.url)}catch(err){status.textContent=err.message;toast(err.message)}finally{button.disabled=false;button.textContent="Open secure Stripe checkout"}};
$("#moreMenu").onclick=()=>{const p=prompt("Open customers, inventory, expenses, reports, staff, delivery, wholesale or stores","customers"),m={customers:"customersPage",inventory:"inventoryPage",expenses:"expensesPage",reports:"reportsPage",staff:"staffPage",delivery:"deliveriesPage",wholesale:"marketplacePage",stores:"storesPage",settings:"settingsPage"};if(m[p?.toLowerCase()])showPage(m[p.toLowerCase()])};
if(session?.accessToken){showApp();Promise.all([loadDashboard(),loadInventory(),loadOrders(),loadProducts()])}else showAuth();
